import logging
from abc import ABC, abstractmethod
from contextlib import contextmanager
from typing import Dict, List, Optional, Union

from taf.ul.telemetry import settings
from taf.ul.telemetry.instrumentation import get_telemetry_instruments
from taf.ul.telemetry.schema import Config, Log, Metric
from taf.ul.telemetry.schema.metrics import MetricType
from taf.ul.telemetry.span import BaseSpan, NoOpSpan, Span
from taf.ul.telemetry.utils import setup_exporters

logger = logging.getLogger(__name__)


class BaseTelemetryAPI(ABC):
    @abstractmethod
    def update(
            self,
            counter_id: str,
            value: Union[int, float],
            metadata: Dict[str, Union[str, bool, float, int]],
    ) -> bool:
        pass

    @abstractmethod
    @contextmanager
    def trace(self, name: str, attributes=None):
        pass

    @abstractmethod
    def start(self, name: str, attributes=None) -> BaseSpan:
        pass

    @abstractmethod
    def stop(self, span: BaseSpan):
        pass

    @abstractmethod
    def add_counter_callback(self, counter_id: str, callbacks):
        pass


class NoOpTelemetryApi(BaseTelemetryAPI):
    def update(
            self,
            counter_id: str,
            value: Union[int, float],
            metadata: Dict[str, Union[str, bool, float, int]],
    ) -> bool:
        return False

    def add_counter_callback(self, counter_id: str, callbacks):
        ...

    @contextmanager
    def trace(self, name: str, attributes=None):
        yield NoOpSpan()

    def start(self, name: str, attributes=None) -> BaseSpan:
        return NoOpSpan()

    def stop(self, span: BaseSpan):
        ...


class TelemetryAPI(BaseTelemetryAPI):
    _default_id = "00000000-0000-0000-0000-000000000000"

    def __init__(self, schema: Config):
        self.internal_tracer, self.internal_meter = get_telemetry_instruments()
        self._setup_exporters()
        self._load_config(schema)

    def _setup_exporters(self):
        self._metric_exporter, self._trace_exporter, self._log_exporter = setup_exporters()

    def _load_config(self, schema: Config):
        with self.internal_tracer.start_as_current_span("load_config"):
            self._setup_resource(schema.resources)
            self._setup_metrics(schema.metrics)
            self._setup_traces()
            self._setup_logs(schema.logs)

    def _setup_resource(self, attributes: Dict[str, Union[int, float, str]]):
        from opentelemetry.sdk.resources import SERVICE_NAME, Resource, SERVICE_INSTANCE_ID
        from taf.ul.telemetry.resources import HostResourceDetector

        resource = Resource.create(attributes=attributes)
        resource = resource.merge(HostResourceDetector().detect())
        self._service_name: str = resource.attributes[SERVICE_NAME]
        self._session_code = resource.attributes.get(SERVICE_INSTANCE_ID, self._default_id)
        self.resource = resource

    def _setup_metrics(self, schema: List[Metric]):
        from opentelemetry import metrics
        from opentelemetry.sdk.metrics import Meter, MeterProvider
        from opentelemetry.sdk.metrics.export import PeriodicExportingMetricReader

        metric_reader = PeriodicExportingMetricReader(
            self._metric_exporter, export_interval_millis=settings._INTERVAL_MS
        )
        with self.internal_tracer.start_as_current_span("metrics"):
            self.metric_provider = MeterProvider([metric_reader], self.resource)

            self.meter: Meter = self.metric_provider.get_meter(settings.INSTRUMENTING_MODULE_NAME)

            self._sync_metrics: Dict[
                str,
                Union[metrics.Counter, metrics.UpDownCounter, metrics.Histogram],
            ] = {}

            self._async_counters: Dict[str, metrics.ObservableCounter] = {}
            logger.debug("number of metrics to setup: %d", len(schema))
            for metric in schema:
                self._setup_meter(metric)

    def _setup_traces(self):
        from opentelemetry.sdk.trace import TracerProvider
        from opentelemetry.sdk.trace.export import BatchSpanProcessor

        with self.internal_tracer.start_as_current_span("traces"):
            self.trace_provider = TracerProvider(resource=self.resource)
            self.trace_provider.add_span_processor(BatchSpanProcessor(self._trace_exporter))

            self.tracer = self.trace_provider.get_tracer(settings.INSTRUMENTING_MODULE_NAME)

    def _setup_logs(self, schema: List[Log]):
        from opentelemetry.sdk._logs import LoggerProvider, LoggingHandler
        from opentelemetry.sdk._logs.export import BatchLogRecordProcessor

        with self.internal_tracer.start_as_current_span("logs"):
            self.log_provider = LoggerProvider(self.resource)
            self.logger = self.log_provider.get_logger(settings.INSTRUMENTING_MODULE_NAME)

            self.log_provider.add_log_record_processor(BatchLogRecordProcessor(self._log_exporter))
            for log in schema:
                logger.debug("adding %s level (%d) to %s handler", log.level.value,
                             logging.getLevelName(log.level.value), log.handler)
                handler = LoggingHandler(
                    level=logging.getLevelName(log.level.value),
                    logger_provider=self.log_provider,
                )
                logging.getLogger(log.handler).addHandler(handler)

    def _setup_meter(self, metric: Metric):
        logger.debug("trying to set up following meter: %s ", metric.name)
        prefix = self._service_name + "_"
        if metric.type == MetricType.Counter:
            self._sync_metrics[metric.name] = self.meter.create_counter(
                prefix + metric.name, metric.unit, metric.description)
        elif metric.type == MetricType.Histogram:
            self._sync_metrics[metric.name] = self.meter.create_histogram(
                prefix + metric.name, metric.unit, metric.description)
        elif metric.type == MetricType.UpDownCounter:
            self._sync_metrics[metric.name] = self.meter.create_up_down_counter(
                prefix + metric.name, metric.unit, metric.description)
        else:
            self._async_counters[metric.name] = metric

    def update(
            self,
            counter_id: str,
            value: Union[int, float],
            metadata: Dict[str, Union[str, bool, float, int]],
    ) -> bool:
        from opentelemetry import metrics
        counter = self._sync_metrics.get(counter_id)
        if not counter:
            logger.debug("Requested counter: %s not found", counter_id)
            return False
        if isinstance(counter, metrics.Histogram):
            counter.record(value, metadata)
        elif isinstance(counter, (metrics.Counter, metrics.UpDownCounter)):
            counter.add(value, metadata)
        else:
            logger.debug("Requested counter: %s was not synchronous")
            return False
        return True

    @contextmanager
    def trace(self, name: str, attributes=None):
        with self.tracer.start_as_current_span(name, attributes=attributes) as span:
            yield Span(span)

    def start(self, name: str, attributes=None) -> BaseSpan:
        return Span(self.tracer.start_span(name, attributes=attributes))

    def stop(self, span: BaseSpan):
        span._span.end()

    def add_counter_callback(self, counter_id: str, callbacks: callable):
        counter: Optional[Metric] = self._async_counters.get(counter_id)
        if counter and isinstance(counter, Metric):
            prefix = self._service_name + "_"
            if counter.type == "async_counter":
                observable_metric = self.meter.create_observable_counter
            elif counter.type == "async_up_down":
                observable_metric = self.meter.create_observable_up_down_counter
            elif counter.type == "gauge":
                observable_metric = self.meter.create_observable_gauge
            else:
                return False
            self._async_counters[counter_id] = observable_metric(
                prefix + counter.name,
                callbacks,
                counter.unit,
                counter.description,
            )
            return True
        return False
